<?php
declare(strict_types=1);require __DIR__.'/inc/db.php';require __DIR__.'/inc/page.php';require __DIR__.'/inc/otp_service.php';$id=(int)($_SESSION['otp_challenge_id']??0);if(!$id)redirect('/AI-CAKE/register.php');$flashNotice=(string)($_SESSION['otp_notice']??'');$flashType=in_array((string)($_SESSION['otp_notice_type']??''),['success','warning','danger'],true)?(string)$_SESSION['otp_notice_type']:'info';unset($_SESSION['otp_notice'],$_SESSION['otp_notice_type']);$error='';$notice=env_bool('SMS_ENABLED')?'Enter the six-digit code sent to your phone.':'SMS delivery is currently unavailable.';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){require_post_csrf();try{$challenge=verify_otp($pdo,$id,trim((string)($_POST['code']??'')));if($challenge['purpose']==='registration'){$pdo->prepare('UPDATE users SET phone_verified_at=NOW(),is_active=1 WHERE id=?')->execute([$challenge['user_id']]);}elseif($challenge['purpose']==='phone_change'){$pdo->prepare('UPDATE users SET phone=?,phone_verified_at=NOW() WHERE id=?')->execute([$challenge['destination'],$challenge['user_id']]);}unset($_SESSION['otp_challenge_id']);redirect('/AI-CAKE/login.php?verified=1');}catch(Throwable $e){$error=$e->getMessage();}}
page_start('Verify phone');?><main class="auth-shell"><section class="app-card auth-card p-4 p-md-5"><div class="eyebrow mb-2">Phone verification</div><h1 class="h3 fw-bold">Enter your code</h1><p class="help-text"><?=e($notice)?></p><?php if($flashNotice):?><div class="alert alert-<?=e($flashType)?>"><?=e($flashNotice)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><label for="code" class="form-label">Six-digit verification code</label><input id="code" name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" class="form-control form-control-lg text-center" required><button class="btn btn-purple w-100 mt-3">Verify phone</button></form><form method="post" action="resend_otp.php" class="mt-3 text-center"><?=csrf_field()?><button class="btn btn-link">Resend code</button></form></section></main><?php page_end();
